// Los alias son etiquetas completas del menú. Un término desconocido se muestra tal como lo publica la guía.
function clave(texto) {
  return texto.trim().toLowerCase().replace(/[-‐‑]/g, ' ').replace(/\s+/g, ' ');
}

function diccionario(grupos) {
  const palabras = new Map();
  for (const [traduccion, variantes] of Object.entries(grupos)) {
    for (const variante of variantes.split('|')) {
      palabras.set(clave(variante), traduccion);
    }
  }
  return palabras;
}

