export function campoES(nombre) {
  return typeof nombre === 'string' ? campos.get(clave(nombre)) ?? nombre : nombre;
}

export function valorES(valor) {
  return typeof valor === 'string' ? valores.get(clave(valor)) ?? valor : valor;
}
